  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const line1Total = 10 * 9500;
  const line1Vat = Math.round(line1Total * 21 / 100);
  const line2Total = 100 * 37;
  const line2Vat = Math.round(line2Total * 9 / 100);
  const line3Total = 1 * 60000;
  const line3Vat = 0;
  const expectedSubtotal = line1Total + line2Total + line3Total;
  const expectedVat = line1Vat + line2Vat + line3Vat;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal + expectedVat);
