test('invoiceTotals with discount and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  const expectedDiscount = Math.round(expectedSubtotal * 5 / 100);
  const vatableAmount = expectedSubtotal - expectedDiscount;
  const expectedVat = Math.round(vatableAmount * 21 / 100);
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with discount 0% VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 1 * 60000;
  const expectedDiscount = Math.round(expectedSubtotal * 5 / 100);
  const expectedVat = 0;
  const expectedTotal = expectedSubtotal - expectedDiscount;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals returns all four properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  assert(totals.hasOwnProperty('subtotal'));
  assert(totals.hasOwnProperty('discount'));
  assert(totals.hasOwnProperty('vat'));
  assert(totals.hasOwnProperty('total'));
});

