test('issueInvoice different years', () => {
  const invoice2025Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });

  const invoice2026Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  assert.equal(invoice2025Result.ok, true);
  assert.equal(invoice2026Result.ok, true);

  const existingNumbers = ['INV-2025-0001'];

  const result2025 = issueInvoice(invoice2025Result.value, existingNumbers);
  assert.equal(result2025.ok, true);
  assert.equal(result2025.value.number, 'INV-2025-0002');

  const result2026 = issueInvoice(invoice2026Result.value, existingNumbers);
  assert.equal(result2026.ok, true);
  assert.equal(result2026.value.number, 'INV-2026-0001');
});

